// Enrich each clinic with the 2-letter state code and the audience name we'll use.
// Robust to both response shapes: HTTP Request returns one item with .json=array,
// or n8n native parses each row into its own item.
const NAME_TO_CODE = {
  Alabama:'AL', Alaska:'AK', Arizona:'AZ', Arkansas:'AR', California:'CA', Colorado:'CO',
  Connecticut:'CT', Delaware:'DE', 'District of Columbia':'DC', Florida:'FL', Georgia:'GA',
  Hawaii:'HI', Idaho:'ID', Illinois:'IL', Indiana:'IN', Iowa:'IA', Kansas:'KS', Kentucky:'KY',
  Louisiana:'LA', Maine:'ME', Maryland:'MD', Massachusetts:'MA', Michigan:'MI', Minnesota:'MN',
  Mississippi:'MS', Missouri:'MO', Montana:'MT', Nebraska:'NE', Nevada:'NV',
  'New Hampshire':'NH', 'New Jersey':'NJ', 'New Mexico':'NM', 'New York':'NY',
  'North Carolina':'NC', 'North Dakota':'ND', Ohio:'OH', Oklahoma:'OK', Oregon:'OR',
  Pennsylvania:'PA', 'Rhode Island':'RI', 'South Carolina':'SC', 'South Dakota':'SD',
  Tennessee:'TN', Texas:'TX', Utah:'UT', Vermont:'VT', Virginia:'VA', Washington:'WA',
  'West Virginia':'WV', Wisconsin:'WI', Wyoming:'WY'
};

const items = $input.all();
let rows = [];
if (items.length === 1 && Array.isArray(items[0].json)) {
  rows = items[0].json;
} else if (items.length === 1 && Array.isArray(items[0].json?.data)) {
  rows = items[0].json.data;
} else {
  rows = items.map(i => i.json);
}

const cfg = $('Config (toggle dry_run)').first().json;
const out = [];
for (const r of rows) {
  if (!r || !r.clinic_id) continue;
  const code = (r.state && r.state.length === 2) ? r.state.toUpperCase() : (NAME_TO_CODE[r.state] || r.state || '');
  out.push({ json: {
    clinic_id: r.clinic_id,
    clinic_name: r.clinic_name,
    state_code: code,
    audience_name: `${r.clinic_name} (${code})`,
    fb_geo_locations: r.fb_geo_locations,
    existing_ids: r.fb_saved_audience_ids || {},
    dry_run: cfg.dry_run,
    supabase_url: cfg.supabase_url,
    graph_api: cfg.graph_api,
    acct_1: cfg.acct_1, acct_2: cfg.acct_2, acct_3: cfg.acct_3,
    acct_4: cfg.acct_4, acct_5: cfg.acct_5, acct_6: cfg.acct_6, acct_7: cfg.acct_7
  }});
}
return out;

// For each of the 7 ad accounts, decide: skip (no active campaigns) | matched (existing audience) | needs_create
// Reads pre-fetched cache from Aggregate Cache (1 HTTP call per endpoint per account, not per-clinic)
// Only ACTIVE campaigns count — paused/archived/deleted historical campaigns don't trigger a create.
const clinic = $('Loop Over Clinics').item.json;
const cache = $('Aggregate Cache').first().json;
const targetName = clinic.audience_name;
const clinicNameLc = clinic.clinic_name.toLowerCase();

// Normalize for fuzzy matching: strip non-alphanumeric so 'Town N Country'
// matches campaigns named 'TheJoint_TownNCountry_...' etc.
function normalize(s) { return (s || '').toLowerCase().replace(/[^a-z0-9]/g, ''); }
const clinicNorm = normalize(clinic.clinic_name);

function findMatch(list) {
  return list.find(x => x.name === targetName)
      || list.find(x => x.name && normalize(x.name).includes(clinicNorm));
}

function findActiveCampaigns(list) {
  return list.filter(x => x.name && normalize(x.name).includes(clinicNorm) && x.status === 'ACTIVE');
}

function decide(accountId, savedAudiences, activeCamps) {
  if (!activeCamps.length) return { account_id: accountId, action: 'skip_no_active_campaigns' };
  const match = findMatch(savedAudiences);
  if (match) return { account_id: accountId, action: 'matched', saved_audience_id: match.id, saved_audience_name: match.name };
  return { account_id: accountId, action: 'needs_create', active_campaign_count: activeCamps.length };
}

const per_account = [];
for (let i = 1; i <= 7; i++) {
  const accountId = clinic[`acct_${i}`];
  if (!accountId) continue;
  const sa = cache.saved_audiences[accountId] || [];
  const allCamps = cache.campaigns[accountId] || [];
  const activeCamps = findActiveCampaigns(allCamps);
  per_account.push(decide(accountId, sa, activeCamps));
}

return [{ json: { ...clinic, per_account } }];

// Emit one item per account that needs_create (skip dry_run skip_no_campaigns matched)
const input = $input.first().json;
const out = [];
for (const acc of input.per_account) {
  if (acc.action !== 'needs_create') continue;
  if (input.dry_run) {
    out.push({ json: { ...input, target_account: acc.account_id, will_create: true, skipped_due_to_dry_run: true } });
    continue;
  }
  out.push({ json: { ...input, target_account: acc.account_id } });
}
return out.length ? out : [];

// Tag the created result back onto the per-clinic per-account record
const created = $input.first().json;
const src = $('Fan-out for Create').item.json;
return [{ json: { ...src, created_saved_audience_id: created.id || null, created_response: created } }];

// After looping, aggregate per-clinic ids: combine matched + created.
// Items entering this node could be: from Decide (already matched) or from Tag Created (newly created)
const all = $input.all();
const byClinic = {};
for (const item of all) {
  const j = item.json;
  const cid = j.clinic_id;
  if (!byClinic[cid]) {
    byClinic[cid] = {
      clinic_id: cid,
      clinic_name: j.clinic_name,
      audience_name: j.audience_name,
      ids: { ...(j.existing_ids || {}) },
      events: []
    };
  }
  // matched audiences come from per_account scan
  if (j.per_account) {
    for (const acc of j.per_account) {
      if (acc.action === 'matched') {
        byClinic[cid].ids[acc.account_id] = acc.saved_audience_id;
        byClinic[cid].events.push({ account: acc.account_id, action: 'matched', saved_audience_id: acc.saved_audience_id, name: acc.saved_audience_name });
      } else if (acc.action === 'skip_no_active_campaigns') {
        byClinic[cid].events.push({ account: acc.account_id, action: 'skip_no_active_campaigns' });
      }
    }
  }
  // newly created audience
  if (j.created_saved_audience_id) {
    byClinic[cid].ids[j.target_account] = j.created_saved_audience_id;
    byClinic[cid].events.push({ account: j.target_account, action: 'created', saved_audience_id: j.created_saved_audience_id });
  } else if (j.skipped_due_to_dry_run) {
    byClinic[cid].events.push({ account: j.target_account, action: 'would_create_dry_run' });
  }
}
return Object.values(byClinic).map(v => ({ json: v }));

// Final report
const items = $input.all();
const summary = items.map(i => ({ clinic_id: i.json.clinic_id, clinic_name: i.json.clinic_name, audience_name: i.json.audience_name, ids: i.json.ids, events: i.json.events }));
return [{ json: { dry_run: $('Config (toggle dry_run)').first().json.dry_run, total_clinics: summary.length, summary } }];

// Emit one item per ad account so HTTP nodes can iterate per-item
const cfg = $('Config (toggle dry_run)').first().json;
const out = [];
for (let i = 1; i <= 7; i++) {
  const id = cfg[`acct_${i}`];
  if (id) out.push({ json: { account_id: id, account_index: i, graph_api: cfg.graph_api } });
}
return out;

// Aggregate per-account responses into a single cache: { saved_audiences: {acct: [...]}, campaigns: {acct: [...]} }
// HTTP nodes paginate: each page becomes its own output item. Use pairedItem to map
// each page back to its source account_id from Emit Per Account.
const emit = $('Emit Per Account').all();
const saItems = $('List Saved Audiences (All Accounts)').all();
const campsItems = $('List Campaigns (All Accounts)').all();

function extractData(item) {
  const j = item.json;
  if (Array.isArray(j)) return j;
  if (Array.isArray(j.data)) return j.data;
  if (Array.isArray(j.body?.data)) return j.body.data;
  return [];
}

function sourceIndex(item) {
  // pairedItem may be a number, an object with .item, or an array of objects
  const p = item.pairedItem;
  if (typeof p === 'number') return p;
  if (Array.isArray(p) && p.length) return p[0].item ?? 0;
  if (p && typeof p === 'object') return p.item ?? 0;
  return 0;
}

const cache = { saved_audiences: {}, campaigns: {} };
for (const a of emit) {
  cache.saved_audiences[a.json.account_id] = [];
  cache.campaigns[a.json.account_id] = [];
}

for (const item of saItems) {
  const idx = sourceIndex(item);
  const acct = emit[idx]?.json.account_id;
  if (!acct) continue;
  cache.saved_audiences[acct].push(...extractData(item));
}

for (const item of campsItems) {
  const idx = sourceIndex(item);
  const acct = emit[idx]?.json.account_id;
  if (!acct) continue;
  cache.campaigns[acct].push(...extractData(item));
}

const counts = {};
for (const a of emit) {
  const acct = a.json.account_id;
  counts[acct] = {
    saved_audiences: cache.saved_audiences[acct].length,
    campaigns: cache.campaigns[acct].length
  };
}

return [{ json: { ...cache, _counts: counts } }];
